# Retrieve the maintenance schedule for all facilities.
schedule_response = requests.get(f"{BASE_URL}/maintenance-schedule")
schedule_response.raise_for_status()
maintenance_schedule = schedule_response.json()

# Retrieve monitored equipment and submit an efficiency evaluation for each item
# with available usage details.
monitoring_response = requests.get(f"{BASE_URL}/equipment-monitoring")
monitoring_response.raise_for_status()
equipment_items = monitoring_response.json().get("equipment", [])

efficiency_evaluations = []
for equipment in equipment_items:
    equipment_id = equipment.get("equipmentId")
    metrics = equipment.get("performanceMetrics", {})
    usage_details = equipment.get("usageDetails") or metrics

    if not equipment_id or not usage_details:
        continue

    evaluation_response = requests.post(
        f"{BASE_URL}/equipment-efficiency-check",
        json={
            "equipmentId": equipment_id,
            "industryId": equipment.get("industryId", "industrial"),
            "usageDetails": (
                usage_details
                if isinstance(usage_details, str)
                else requests.compat.json.dumps(usage_details)
            ),
        },
    )
    evaluation_response.raise_for_status()
    efficiency_evaluations.append(evaluation_response.json())

# Review schedule entries and flag missing or potentially inaccurate report data.
schedule_feedback = []
for entry in maintenance_schedule:
    issues = []
    if not entry.get("facility"):
        issues.append("Facility is missing.")
    if not entry.get("activity"):
        issues.append("Maintenance activity is missing.")
    if not entry.get("date"):
        issues.append("Scheduled date is missing.")
    if entry.get("status") not in {"Pending", "Completed", "In Progress"}:
        issues.append("Status is missing or invalid.")

    schedule_feedback.append(
        {
            "scheduleId": entry.get("id"),
            "feedback": issues or [
                "Entry contains the documented facility, activity, date, and status fields; verify these against facility records for accuracy."
            ],
            "suggestedImprovement": (
                "Add the missing or invalid fields and validate dates and statuses against operational records."
                if issues
                else "Include equipment identifiers, maintenance rationale, and completion evidence to improve report accuracy."
            ),
        }
    )

print(
