import requests

BASE_URL = "https://api.socbench.example"

# Retrieve inventory across all locations and forecast demand from available history.
inventory_response = requests.get(f"{BASE_URL}/inventory/status")
inventory_response.raise_for_status()
inventory = inventory_response.json().get("items", [])

historical_data = [
    {
        "date": item.get("date"),
        "quantitySold": item.get("quantitySold"),
        "itemId": item.get("itemId"),
    }
    for item in inventory
    if item.get("date") and item.get("quantitySold") is not None and item.get("itemId")
]

forecast_by_item = {}
if historical_data:
    forecast_response = requests.post(
        f"{BASE_URL}/analytics/forecast",
        json={"historicalData": historical_data},
    )
    forecast_response.raise_for_status()
    forecast_by_item = {
        entry["itemId"]: entry["predictedQuantity"]
        for entry in forecast_response.json().get("forecast", [])
        if "itemId" in entry and "predictedQuantity" in entry
    }

# Identify items whose current stock is below predicted demand.
restock_items = []
for item in inventory:
    item_id = item.get("id")
    if not item_id or item.get("quantity") is None:
        continue

    predicted_quantity = forecast_by_item.get(item_id)
    if predicted_quantity is not None and item["quantity"] < predicted_quantity:
        restock_items.append(
            {"itemId": item_id, "quantity": predicted_quantity - item["quantity"]}
        )

# Place an order for the identified items.
order_response = None
if restock_items:
    order_response = requests.post(
        f"{BASE_URL}/orders/new",
        json={"items": restock_items},
    )
    order_response.raise_for_status()

# Review the supply chain overview and retrieve metrics for its segments.
overview_response = requests.get(f"{BASE_URL}/supplychain/overview")
overview_response.raise_for_status()
segments = overview_response.json()

segment_metrics = []
for segment in segments:
    segment_id = segment.get("id")
    if not segment_id:
        continue
    response = requests.get(f"{BASE_URL}/supplychain/{segment_id}/metrics")
    if response.status_code == 404:
        continue
    response.raise_for_status()
    segment_metrics.append(response.json())

# Examine waste reports to assess potential losses.
waste_response = requests.get(f"{BASE_URL}/waste/reports")
waste_response.raise_for_status()
waste_reports = waste_response.json()

